const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const COLORS={Finder:'#4c91dc',Files:'#4c91dc',Safari:'#69a9e9',Browser:'#4d94dd',Mail:'#72b8e5',Messages:'#58ba85',Calendar:'#fff',Photos:'#e9eef4',Music:'#d95a79',Notes:'#efc34d',Reminders:'#fafafa',Calculator:'#28364a',Clock:'#344053',Weather:'#61a8d8',Settings:'#737d90',Terminal:'#1a222d','Activity Monitor':'#7858c7',Preview:'#8798aa',Trash:'#d7e0e8','Canopy Guide':'#57bc91',Maps:'#67b481',Contacts:'#77a9d9','Voice Memos':'#dc6b7d',Downloads:'#7495bc'};
const APPS=[['Finder','📁','Your files, folders, and recent items'],['Safari','🌐','A calm window to the web'],['Mail','✉️','Your messages, all in one place'],['Messages','💬','Conversations and quick replies'],['Calendar','▦','Plan your days and events'],['Photos','🌄','A home for your favorite moments'],['Music','♫','A little soundtrack for your day'],['Notes','📝','Thoughts, lists, and quick notes'],['Reminders','☑','The things you want to remember'],['Calculator','🧮','Quick, scientific, and always ready'],['Clock','◷','World clocks, alarms, timers'],['Weather','☀','A glance at the sky'],['Settings','⚙','Make Canopy yours'],['Terminal','⌘','A tiny command line'],['Activity Monitor','◉','A quick look under the hood'],['Preview','▧','Look closer at a file'],['Maps','⌖','Places near and far'],['Contacts','♙','People you keep close'],['Voice Memos','🎙','Capture a thought'],['Downloads','⇩','Recently downloaded files'],['Canopy Guide','✦','A guide to the essentials'],['Trash','▱','Recover or clear deleted files']].map(([name,icon,desc])=>({name,icon,desc,color:COLORS[name]||'#657a94'}));
const getPrefs=()=>{try{return JSON.parse(localStorage.getItem('canopy.prefs'))||{}}catch{return {}}};
const prefs={wallpaper:'aurora',live:true,speed:1,brightness:85,volume:45,reduceMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,clock24:false,dark:false,widgets:true,focus:false,wallpaperGlow:true,...getPrefs()};
let notes=localStorage.getItem('canopy.notes')||'Welcome to CanopyOS.\n\nA quiet place to collect your thoughts. This note saves automatically.';
let reminders=JSON.parse(localStorage.getItem('canopy.reminders')||'[]'),events=JSON.parse(localStorage.getItem('canopy.events')||'{}');
let files=JSON.parse(localStorage.getItem('canopy.files')||'null')||[{name:'Getting Started',icon:'📄',type:'Document',date:'Today'},{name:'Weekend plans',icon:'📝',type:'Note',date:'Yesterday'},{name:'Inspiration',icon:'📁',type:'Folder',date:'Oct 28'},{name:'Canopy wallpaper',icon:'🖼️',type:'Image',date:'Oct 26'},{name:'Project brief.pdf',icon:'📕',type:'PDF',date:'Oct 24'},{name:'Welcome.txt',icon:'📄',type:'Text file',date:'Oct 20'},{name:'Downloads',icon:'⇩',type:'Folder',date:'Oct 19'}];
let windowCounter=0,windows=new Map(),zTop=10,calendarDate=new Date(),calc={current:'0',stored:null,operator:null,reset:false},browserPage='Canopy Start',termHistory=[],musicPlaying=false,musicIndex=0,timerInterval=null,activeFolder='Home';
const wallpapers={aurora:{name:'Aurora',base:['#07172e','#064b59','#388f79']},ocean:{name:'Ocean',base:['#08264a','#0b6995','#68cdbb']},dusk:{name:'Dusk',base:['#21133d','#824567','#e48a69']},ember:{name:'Ember',base:['#171622','#803b37','#eca35a']},forest:{name:'Forest',base:['#0d261d','#236443','#a4c77e']},cosmos:{name:'Cosmos',base:['#0e0d2b','#423882','#c75fa8']}};
function savePrefs(){localStorage.setItem('canopy.prefs',JSON.stringify(prefs))}function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toasts').append(el);setTimeout(()=>el.remove(),2800)}
function updateClock(){let d=new Date();$('#clock').textContent=d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})+'  '+d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',hour12:!prefs.clock24});$('#widgetMonth').textContent=d.toLocaleDateString(undefined,{month:'long',year:'numeric'}).toUpperCase();$('#widgetDay').textContent=d.getDate()}updateClock();setInterval(updateClock,1000);
const canvas=$('#wallpaper'),ctx=canvas.getContext('2d');let cw=0,ch=0,dpr=1,lastFrame=0,phase=0,stars=[],blobs=[],hasDrawn=false,lastWallpaper='',lastBrightness=-1,lastGlow=null;
function resizeCanvas(){hasDrawn=false;dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:Math.min(100,Math.floor(cw*ch/11000))},()=>({x:Math.random()*cw,y:Math.random()*ch,r:Math.random()*1.5+.3,p:Math.random()*6.28,s:Math.random()*.8+.2}));blobs=Array.from({length:5},(_,i)=>({x:cw*(.12+i*.19),y:ch*(.3+Math.random()*.45),r:Math.min(cw,ch)*(.22+Math.random()*.17),p:Math.random()*6.28}))}addEventListener('resize',resizeCanvas);resizeCanvas();
function drawWallpaper(now){requestAnimationFrame(drawWallpaper);const dirty=!hasDrawn||lastWallpaper!==prefs.wallpaper||lastBrightness!==prefs.brightness||lastGlow!==prefs.wallpaperGlow;if(document.hidden||((!prefs.live||prefs.reduceMotion)&&hasDrawn&&!dirty))return;if(now-lastFrame<24&&!dirty)return;let dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;if(prefs.live&&!prefs.reduceMotion)phase+=dt*(prefs.speed||1)*.22;let w=wallpapers[prefs.wallpaper]||wallpapers.aurora;ctx.clearRect(0,0,cw,ch);let g=ctx.createLinearGradient(0,0,cw,ch);g.addColorStop(0,w.base[0]);g.addColorStop(.55,w.base[1]);g.addColorStop(1,w.base[2]);ctx.fillStyle=g;ctx.fillRect(0,0,cw,ch);ctx.globalCompositeOperation='screen';for(let i=0;i<blobs.length;i++){let b=blobs[i],x=b.x+Math.sin(phase*.8+b.p)*cw*.12,y=b.y+Math.cos(phase*.61+b.p)*ch*.09,rg=ctx.createRadialGradient(x,y,0,x,y,b.r);rg.addColorStop(0,`rgba(${i%2?'73,226,177':'93,155,255'},${prefs.wallpaperGlow?.34:.18})`);rg.addColorStop(1,'rgba(10,28,45,0)');ctx.fillStyle=rg;ctx.fillRect(x-b.r,y-b.r,b.r*2,b.r*2)}
if(prefs.wallpaper==='aurora'||prefs.wallpaper==='cosmos'){for(let band=0;band<4;band++){ctx.beginPath();for(let x=-5;x<=cw+5;x+=8){let y=ch*(.22+band*.075)+Math.sin(x*.004+phase+band)*ch*.07+Math.sin(x*.009-phase*.7)*ch*.025;if(x===-5)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.lineTo(cw,ch*.68);ctx.lineTo(0,ch*.68);ctx.closePath();let rg=ctx.createLinearGradient(0,ch*.2,0,ch*.75);rg.addColorStop(0,`rgba(${band%2?'80,220,175':'67,142,245'},0)`);rg.addColorStop(.5,`rgba(${band%2?'64,210,155':'87,141,255'},${.07+Math.sin(phase+band)*.025})`);rg.addColorStop(1,'rgba(20,45,78,0)');ctx.fillStyle=rg;ctx.fill()}}else if(prefs.wallpaper==='ocean'){for(let n=0;n<5;n++){ctx.beginPath();for(let x=0;x<=cw;x+=6){let y=ch*(.6+n*.07)+Math.sin(x*.008+phase+n)*ch*.018+Math.sin(x*.003-phase*.7)*ch*.012;if(!x)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle=`rgba(143,239,224,${.11-n*.012})`;ctx.lineWidth=2;ctx.stroke()}}else if(prefs.wallpaper==='ember'){for(let i=0;i<26;i++){let x=(i*97+Math.sin(phase+i)*20)%cw,y=ch-((phase*18+i*41)%(ch+50)),a=Math.max(0,1-y/ch);ctx.fillStyle=`rgba(255,${150+i%80},75,${a*.38})`;ctx.beginPath();ctx.arc(x,y,1+(i%3),0,Math.PI*2);ctx.fill()}}else if(prefs.wallpaper==='forest'){for(let i=0;i<25;i++){let x=(i*71+Math.sin(phase*.5+i)*25)%cw,y=(i*113+phase*8)%ch;ctx.fillStyle=`rgba(195,240,157,${.12+Math.sin(phase+i)*.05})`;ctx.beginPath();ctx.arc(x,y,1.2,0,Math.PI*2);ctx.fill()}}if(prefs.wallpaper==='cosmos'||prefs.wallpaper==='aurora'){ctx.globalCompositeOperation='source-over';for(let s of stars){ctx.fillStyle=`rgba(245,250,255,${.26+.6*(.5+.5*Math.sin(phase*s.s+s.p))})`;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill()}}ctx.globalCompositeOperation='source-over';ctx.fillStyle=`rgba(255,255,255,${Math.max(0,Math.min(prefs.brightness,100))/100*.055})`;ctx.fillRect(0,0,cw,ch);hasDrawn=true;lastWallpaper=prefs.wallpaper;lastBrightness=prefs.brightness;lastGlow=prefs.wallpaperGlow}requestAnimationFrame(drawWallpaper);
function iconStyle(app){return `background:${app.color||'#72849b'}`}
function renderDock(){$('#dock').innerHTML=APPS.filter(a=>!['Trash','Canopy Guide','Downloads','Preview','Voice Memos'].includes(a.name)).map(a=>`<button class="dock-icon" data-app="${esc(a.name)}" title="${esc(a.name)}"><span class="app-glyph" style="${iconStyle(a)}">${a.icon}</span>${[...windows.values()].some(w=>w.app===a.name&&!w.minimized)?'<i class="running-dot"></i>':''}</button>`).join('')}
function renderApp(name){switch(name){case'Notes':return notesUI();case'Finder':case'Files':return filesUI();case'Settings':return settingsUI();case'Calendar':return calendarUI();case'Calculator':return calculatorUI();case'Terminal':return terminalUI();case'Safari':case'Browser':return browserUI();case'Reminders':return remindersUI();case'Clock':return clockUI();case'Activity Monitor':return monitorUI();case'Music':return musicUI();case'Photos':return photosUI();case'Weather':return weatherUI();case'Mail':return mailUI();case'Messages':return messagesUI();case'Maps':return mapsUI();case'Contacts':return contactsUI();case'Preview':return previewUI();case'Voice Memos':return voiceUI();case'Downloads':return filesUI('Downloads');case'Trash':return trashUI();default:return guideUI()}}
function notesUI(){return `<div class="app-content" style="height:100%;position:relative"><div class="app-toolbar"><button data-action="note-new">＋ New note</button><span class="toolbar-spacer"></span><button data-action="note-copy">Copy</button><button data-action="note-clear">Clear</button></div><textarea class="note-editor" id="noteEditor" placeholder="Start writing…">${esc(notes)}</textarea><div class="note-meta" id="noteMeta">Saved to this device</div></div>`}
function filesUI(folder='Home'){activeFolder=folder;return `<div class="app-content split-layout"><aside class="sidebar"><div class="sidebar-label">Favorites</div>${[['⌂','Home'],['▣','Desktop'],['⇩','Downloads'],['◷','Recents'],['☁','Canopy Drive']].map(([i,n])=>`<button class="sidebar-item ${folder===n?'active':''}" data-folder="${n}"><span>${i}</span>${n}</button>`).join('')}<div class="sidebar-label" style="margin-top:16px">Tags</div>${[['Personal','#76b89b'],['Work','#709be0'],['Important','#e4ab58']].map(([n,c])=>`<button class="sidebar-item"><span style="color:${c}">●</span>${n}</button>`).join('')}</aside><section class="main-pane"><div class="app-toolbar" style="margin:-20px -20px 18px"><button data-action="file-new-folder">＋ New folder</button><button data-action="file-new-note">＋ Note</button><span class="toolbar-spacer"></span><button data-action="file-sort">⇅ Sort</button><button data-action="file-view">▦</button></div><h2 class="app-title">${esc(folder)}</h2><p class="app-subtitle">Your files, right where you left them</p><div class="file-grid">${files.filter(f=>folder==='Home'||folder==='Recents'||folder==='Downloads'&&f.type==='Download'||folder==='Desktop'&&f.type==='Desktop'||folder==='Canopy Drive'&&f.cloud).map((f,i)=>`<button class="file-item" data-file="${i}" title="${esc(f.type)} · ${esc(f.date)}"><span>${f.icon}</span>${esc(f.name)}</button>`).join('')||'<div class="small-status">This folder is empty</div>'}</div></section></div>`}
function settingsUI(){return `<div class="app-content split-layout"><aside class="sidebar"><div class="sidebar-label">System Settings</div>${[['⚙','General'],['◈','Appearance'],['▣','Desktop & Dock'],['◉','Wallpaper'],['⌨','Keyboard'],['♿','Accessibility'],['🔔','Notifications'],['🔋','Battery'],['⌁','Network'],['🔒','Privacy & Security'],['☁','Canopy Account'],['ⓘ','About Canopy']].map(([i,n],ix)=>`<button class="sidebar-item ${ix===0?'active':''}" data-settings-tab="${n}"><span>${i}</span>${n}</button>`).join('')}</aside><section class="main-pane" id="settingsPane">${settingsPanel('General')}</section></div>`}
function toggleRow(label,key,val){return `<div class="toggle-row"><span>${label}</span><button class="toggle-switch ${val?'on':''}" data-pref="${key}" aria-label="Toggle ${label}"></button></div>`}
function settingsPanel(tab){if(['Wallpaper','Appearance','Desktop & Dock'].includes(tab))return `<h2 class="app-title">${tab}</h2><p class="app-subtitle">Personalize your desktop without adding visual clutter.</p><div class="card"><h3>Animated wallpaper</h3><p>Choose an ambient scene. Wallpapers render live with a lightweight canvas animation.</p><div class="wallpaper-options">${Object.entries(wallpapers).map(([id,w])=>`<button class="wallpaper-choice ${prefs.wallpaper===id?'active':''}" data-wall="${id}">${w.name} ${prefs.wallpaper===id?'✓':''}</button>`).join('')}</div>${toggleRow('Live motion','live',prefs.live)}<label class="toggle-row"><span>Animation speed <small class="small-status">${prefs.speed.toFixed(1)}×</small><input class="settings-range" type="range" min=".3" max="2" step=".1" value="${prefs.speed}" data-pref-range="speed"></span></label>${toggleRow('Ambient glow','wallpaperGlow',prefs.wallpaperGlow)}</div><div class="card"><h3>Desktop widgets</h3>${toggleRow('Show weather and date widgets','widgets',prefs.widgets)}${toggleRow('Show desktop icons','desktopIcons',getPrefs().desktopIcons!==false)}${toggleRow('Reduce motion','reduceMotion',prefs.reduceMotion)}</div>`;
if(tab==='Keyboard')return `<h2 class="app-title">Keyboard</h2><p class="app-subtitle">Useful shortcuts, always within reach.</p><div class="card">${[['⌘ Space','Open search'],['⌘ ⇧ A','Open app launcher'],['⌘ N','New note'],['⌘ ,','Open settings'],['⌘ W','Close front window'],['⌘ M','Minimize front window'],['Esc','Close menus and panels']].map(([a,b])=>`<div class="toggle-row"><b>${a}</b><span class="small-status">${b}</span></div>`).join('')}</div>`;
if(tab==='Accessibility')return `<h2 class="app-title">Accessibility</h2><p class="app-subtitle">Make your workspace more comfortable.</p><div class="card">${toggleRow('Reduce motion','reduceMotion',prefs.reduceMotion)}${toggleRow('High contrast','highContrast',!!prefs.highContrast)}${toggleRow('Larger interface','largeText',!!prefs.largeText)}<p>Canopy respects system reduced-motion preferences and pauses wallpaper animation.</p></div>`;
if(tab==='Notifications')return `<h2 class="app-title">Notifications</h2><div class="card"><h3>Notification preferences</h3>${toggleRow('Do Not Disturb','focus',prefs.focus)}${toggleRow('Show notification previews','previews',true)}<button class="primary" data-action="notify-test">Send test notification</button></div>`;
if(tab==='Battery')return `<h2 class="app-title">Battery</h2><p class="app-subtitle">Power use is estimated for this browser session.</p><div class="card"><div class="stats-row"><div class="stat-card"><small>BATTERY</small><b>100%</b></div><div class="stat-card"><small>POWER SOURCE</small><b>Adapter</b></div><div class="stat-card"><small>WALLPAPER</small><b>${prefs.live?'Live':'Paused'}</b></div></div><p>Live wallpaper pauses automatically when this tab is hidden.</p></div>`;
if(tab==='Network')return `<h2 class="app-title">Network</h2><div class="card"><h3>Wi-Fi</h3><div class="toggle-row">Canopy Network <small class="small-status">Connected · Excellent</small></div><p>Private address · Security: WPA2 Personal</p></div><div class="card"><h3>Nearby networks</h3><div class="toggle-row">Canopy Guest <span class="small-status">Secured · ▰▰▰</span></div></div>`;
if(tab==='Privacy & Security')return `<h2 class="app-title">Privacy & Security</h2><p class="app-subtitle">Your data stays in this browser on this device.</p><div class="card">${toggleRow('Lock screen on wake','lockscreen',false)}${toggleRow('Allow analytics','analytics',false)}<button data-action="clear-data" class="app-input danger">Clear local Canopy data…</button></div>`;
if(tab==='About Canopy')return `<h2 class="app-title">About CanopyOS</h2><div class="card"><div style="font-size:45px;text-align:center">◈</div><h3 style="text-align:center">CanopyOS 0.2</h3><p style="text-align:center">A calm, capable desktop for the web.</p><p>Built with care. CanopyOS is an open-source desktop experience and is not affiliated with Apple.</p><button data-action="show-guide" class="primary">Explore the Canopy Guide</button></div>`;
return `<h2 class="app-title">${tab}</h2><p class="app-subtitle">A workspace that feels like yours.</p><div class="settings-grid">${[['◉','Wallpaper','Animated scenes & ambient motion'],['◈','Appearance','Light, dark, or automatic'],['▣','Desktop & Dock','Widgets, icons, and dock behavior'],['⌨','Keyboard','Shortcuts and input'],['♿','Accessibility','Motion, contrast, and text'],['🔔','Notifications','Quiet hours and previews'],['🔋','Battery','Power and animation behavior'],['⌁','Network','Wi-Fi and connections'],['🔒','Privacy & Security','Local data and privacy']].map(([i,n,d])=>`<button class="settings-category" data-settings-tab="${n}"><span class="result-icon" style="background:#edf2f8">${i}</span><b>${n}</b><small>${d}</small></button>`).join('')}</div><div class="card" style="margin-top:14px"><h3>Quick preferences</h3>${toggleRow('Dark appearance','dark',prefs.dark)}${toggleRow('24-hour clock','clock24',prefs.clock24)}${toggleRow('Reduce motion','reduceMotion',prefs.reduceMotion)}</div>`}
function calendarUI(){let y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),today=new Date(),cells=Array(first).fill('<div></div>').concat(Array.from({length:days},(_,i)=>{let d=i+1,key=`${y}-${m+1}-${d}`;return `<div class="calendar-day ${d===today.getDate()&&m===today.getMonth()&&y===today.getFullYear()?'today':''} ${events[key]?.length?'has-event':''}" data-day="${key}">${d}</div>`}));return `<div class="app-content" style="padding:20px"><div class="calendar-head"><div><button data-action="cal-prev">‹</button> <button data-action="cal-next">›</button></div><h2>${calendarDate.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><button class="app-input" data-action="cal-today">Today</button></div><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells.join('')}</div><div class="card" style="margin-top:16px"><h3>Upcoming</h3>${Object.entries(events).filter(([,v])=>v.length).slice(0,4).map(([k,v])=>`<p>● ${esc(k)} — ${esc(v.join(', '))}</p>`).join('')||'<p>Nothing planned yet. Click a date to add an event.</p>'}</div></div>`}
function calculatorUI(){return `<div class="calculator"><div class="calc-display"><div class="calc-expression" id="calcExpr"></div><div class="calc-result" id="calcResult">${esc(calc.current)}</div></div><div class="calc-grid">${['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','=',''].map(k=>`<button class="calc-key ${['AC','±','%'].includes(k)?'action':''} ${['÷','×','−','+'].includes(k)?'operator':''} ${k==='='?'equals':''} ${k==='0'?'zero':''}" data-calc="${k}">${k}</button>`).join('')}</div></div>`}
function terminalUI(){return `<div class="terminal" id="terminal"><div>Canopy Terminal · shell 1.0</div><div>Type <b>help</b> to see available commands.</div><div id="termOutput"></div><div class="terminal-input-row"><span>guest@canopy:~$&nbsp;</span><input class="terminal-input" id="termInput" autocomplete="off" spellcheck="false"></div></div>`}
function browserUI(){return `<div class="browser-frame"><div class="app-toolbar"><button data-action="browser-back">‹</button><button data-action="browser-forward">›</button><button data-action="browser-reload">↻</button><input class="app-input browser-address" id="browserAddress" value="canopy://start" placeholder="Search or enter address"><button data-action="browser-go">Go</button></div><div class="browser-page" id="browserPage">${browserHome()}</div></div>`}
function browserHome(){return `<div class="browser-hero"><span>◈ CANOPY WEB</span><h1>Take a breath.</h1><p>A quieter corner of the internet starts right here.</p><input class="app-input" id="webSearch" style="width:min(430px,100%)" placeholder="Search the web (simulated)"><button class="primary" data-action="web-search">Search</button></div><div class="browser-links">${[['⌂','Canopy Guide','Helpful tips for your desktop.'],['☀','Local weather','A sunny day in San Diego.'],['▦','Today','Check your calendar and reminders.'],['🔒','Privacy','Your browsing stays local.'],['🗞','Reading list','A small space for what you want to read.'],['✦','Discover','Find something lovely to do.']].map(([i,n,d])=>`<button class="browser-link" data-web="${n}"><span>${i}</span><b>${n}</b><small>${d}</small></button>`).join('')}</div>`}
function remindersUI(){return `<div class="app-content" style="padding:22px"><h2 class="app-title">Reminders</h2><p class="app-subtitle">Keep the little things from slipping away.</p><div class="app-toolbar" style="padding:0;border:0;background:transparent"><input class="app-input" id="reminderInput" placeholder="Add a reminder…" style="flex:1"><button class="primary" data-action="reminder-add">Add</button></div><div class="card" style="margin-top:16px"><h3>Today · ${reminders.filter(r=>!r.done).length} remaining</h3>${reminders.map((r,i)=>`<label class="reminder-row ${r.done?'completed':''}"><input type="checkbox" data-reminder="${i}" ${r.done?'checked':''}><span>${esc(r.text)}</span><span class="toolbar-spacer"></span><button data-reminder-delete="${i}" class="danger">×</button></label>`).join('')||'<p>No reminders yet. Add one above.</p>'}</div><div class="card"><h3>Smart Lists</h3><p>Today · Scheduled · Flagged · Completed</p></div></div>`}
let cities=['New York','London','Tokyo'];function worldCities(){return cities.map(c=>`<div class="world-clock-row"><div><b>${new Date().toLocaleTimeString('en-US',{timeZone:({'New York':'America/New_York',London:'Europe/London',Tokyo:'Asia/Tokyo','San Diego':'America/Los_Angeles'})[c]||'UTC',hour:'numeric',minute:'2-digit'})}</b><small>${c}</small></div><span class="small-status">${c==='London'||c==='Tokyo'?'Tomorrow':'Today'}</span></div>`).join('')}
function clockUI(){return `<div class="app-content" style="padding:18px"><div class="card" style="text-align:center"><h2 class="app-title" id="bigClock">--:--</h2><p class="app-subtitle">San Diego · Local time</p></div><div class="app-toolbar" style="padding:0;border:0;background:transparent"><b>World Clock</b><span class="toolbar-spacer"></span><button data-action="clock-add">＋ Add city</button></div><div id="worldClocks">${worldCities()}</div><div class="card"><h3>Timer</h3><div style="display:flex;gap:8px;align-items:center"><input class="app-input" type="number" id="timerMinutes" value="5" min="1" max="999" style="width:80px"><span>minutes</span><button class="primary" data-action="timer-start">Start</button><b id="timerDisplay" style="margin-left:auto">Ready</b></div></div><div class="card"><h3>Stopwatch</h3><div style="display:flex;gap:10px;align-items:center"><b id="stopwatchDisplay">00:00.0</b><button data-action="stopwatch-toggle" class="app-input">Start</button><button data-action="stopwatch-reset" class="app-input">Reset</button></div></div></div>`}
function monitorUI(){return `<div class="app-content" style="padding:18px"><h2 class="app-title">Activity Monitor</h2><p class="app-subtitle">A lightweight view of your Canopy session.</p><div class="stats-row"><div class="stat-card"><small>CPU LOAD</small><b id="cpuStat">12%</b></div><div class="stat-card"><small>MEMORY</small><b id="memStat">1.4 GB</b></div><div class="stat-card"><small>NETWORK</small><b>Idle</b></div></div><div class="card" style="margin-top:14px"><h3>Apps running</h3><div id="processList"></div></div><div class="card"><h3>Energy</h3><p>Live wallpapers pause when the page is hidden and render at an efficient frame rate.</p></div></div>`}
function musicUI(){let tracks=['Golden Hour','Open Window','Soft Landing','Coastal Drive'];return `<div class="app-content" style="padding:18px;text-align:center"><div class="music-art">${['♫','☼','✦','☁'][musicIndex%4]}</div><h2 class="app-title">${tracks[musicIndex%4]}</h2><p class="app-subtitle">Canopy Radio · ${['Morning Light','Easy Listening','Daydreams','Weekend Mix'][musicIndex%4]}</p><input class="progress" type="range" min="0" max="100" value="${musicPlaying?32:0}"><div style="display:flex;justify-content:space-between" class="small-status"><span>1:24</span><span>3:42</span></div><div class="music-controls"><button data-action="music-prev">⏮</button><button class="play-button" data-action="music-play">${musicPlaying?'Ⅱ':'▶'}</button><button data-action="music-next">⏭</button></div><div class="card" style="text-align:left;margin-top:17px"><h3>Up next</h3>${tracks.map((t,i)=>`<div class="toggle-row"><span>${i+1}. ${t}</span><button data-track="${i}" class="small-status">▶</button></div>`).join('')}</div><p class="small-status">Demo player · Audio streaming isn't connected</p></div>`}
function photosUI(){return `<div class="app-content" style="padding:20px"><h2 class="app-title">Photos</h2><p class="app-subtitle">Little moments, collected.</p><div class="app-toolbar" style="padding:0;border:0;background:transparent"><button class="primary" data-action="photo-import">＋ Import</button><span class="toolbar-spacer"></span><button data-action="photo-sort">Sort by date</button></div><div class="photo-grid" style="margin-top:15px">${['Coastline','Golden hour','Blue hour','Ocean air','Sunday market','Green escape'].map((t,i)=>`<button class="photo-tile" data-photo="${t}" title="${t}">${['🌊','🌅','🌌','🐚','🌼','🌿'][i]}</button>`).join('')}</div><p class="small-status" style="margin-top:10px">Sample albums · Photos stay on this device</p></div>`}
function weatherUI(){return `<div class="app-content" style="padding:22px"><h2 class="app-title">San Diego</h2><p class="app-subtitle">Today · Mostly sunny</p><div class="card" style="display:flex;align-items:center;gap:25px"><span style="font-size:62px;color:#efbd53">☀</span><div><b style="font:500 55px Manrope">72°</b><p>Feels like 71° · High 76° · Low 61°</p></div></div><div class="card"><h3>Hourly forecast</h3><div style="display:flex;justify-content:space-between;text-align:center">${['Now','11 AM','12 PM','1 PM','2 PM','3 PM'].map((h,i)=>`<div><small class="small-status">${h}</small><p>☀</p><b>${[72,73,74,76,75,73][i]}°</b></div>`).join('')}</div></div><div class="card"><h3>10-day forecast</h3><p>Sunny and mild through the weekend. A little coastal breeze in the afternoon.</p></div><p class="small-status">Demo forecast for San Diego · No location tracking</p></div>`}
function mailUI(){return `<div class="app-content split-layout"><aside class="sidebar"><div class="sidebar-label">Mailboxes</div>${[['✉','Inbox'],['✦','Starred'],['◷','Snoozed'],['▤','Drafts'],['⇧','Sent'],['▱','Archive']].map(([i,n])=>`<button class="sidebar-item" data-mailbox="${n}"><span>${i}</span>${n}</button>`).join('')}</aside><section class="main-pane"><div style="display:flex;justify-content:space-between"><h2 class="app-title" id="mailTitle">Inbox</h2><button class="primary" data-action="mail-compose">Compose</button></div><p class="app-subtitle">A clean, local-only mail preview.</p>${[['Welcome to Canopy','Your desktop, your way.','10:42 AM'],['A little breathing room','Three ideas to make today easier.','Yesterday'],['Your weekly note','A quiet recap of what matters.','Mon']].map(([a,b,c],i)=>`<button class="card" data-mail="${i}" style="text-align:left;width:100%;color:inherit"><b style="font-size:11px">${a}</b><span class="small-status" style="float:right">${c}</span><p>${b}</p></button>`).join('')}</section></div>`}
function messagesUI(){return `<div class="app-content split-layout"><aside class="sidebar"><div class="sidebar-label">Conversations</div>${['Maya Chen','Jordan Lee','Family group'].map((n,i)=>`<button class="sidebar-item ${i===0?'active':''}" data-chat="${n}"><span>${['🟢','🟣','🟡'][i]}</span>${n}</button>`).join('')}<button class="sidebar-item" data-action="chat-new">＋ New message</button></aside><section class="main-pane" style="display:flex;flex-direction:column"><h2 class="app-title" id="chatTitle">Maya Chen</h2><div class="card" id="chatMessages" style="flex:1;overflow:auto"><p><b>Maya</b> · Hey! Are we still on for Saturday?</p><p style="text-align:right;color:#5689df">Absolutely. See you at noon! · You</p><p><b>Maya</b> · Perfect 🌿</p></div><div style="display:flex;gap:7px"><input class="app-input" id="chatInput" placeholder="Message" style="flex:1"><button class="primary" data-action="chat-send">Send</button></div></section></div>`}
function mapsUI(){return `<div class="app-content" style="padding:20px"><div style="display:flex;gap:8px"><input class="app-input" id="mapSearch" placeholder="Search places" style="flex:1"><button class="primary" data-action="map-search">Search</button></div><div class="card" style="height:265px;margin-top:13px;background:linear-gradient(45deg,#c6dfc6 0 25%,#dbe6ca 25% 50%,#c1d9c8 50% 75%,#e3e8d4 75%);position:relative"><div style="position:absolute;background:#a5cee0;inset:0 0 0 57%;clip-path:polygon(35% 0,100% 0,100% 100%,0 100%)"></div><div style="position:absolute;left:43%;top:42%;font-size:25px">📍</div><div style="position:absolute;left:22%;top:26%;background:#fff;padding:5px 8px;border-radius:9px;font-size:9px">Balboa Park</div><div style="position:absolute;left:55%;top:68%;background:#fff;padding:5px 8px;border-radius:9px;font-size:9px">La Jolla Cove</div><div style="position:absolute;right:14px;bottom:12px;background:#ffffffbb;padding:7px;border-radius:8px;font-size:9px">SAN DIEGO</div></div><div class="card"><h3>Explore nearby</h3><p>Balboa Park · 2.4 mi &nbsp; · &nbsp; La Jolla Cove · 12 mi &nbsp; · &nbsp; Sunset Cliffs · 6 mi</p><p class="small-status">Illustrative map; navigation isn't connected.</p></div></div>`}
function contactsUI(){return `<div class="app-content" style="padding:20px"><div class="app-toolbar" style="margin:-20px -20px 18px"><input class="app-input" id="contactSearch" placeholder="Search contacts" style="flex:1"><button class="primary" data-action="contact-add">＋ Add Contact</button></div><h2 class="app-title">Contacts</h2><p class="app-subtitle">People and details saved locally.</p><div id="contactsList">${[['MC','Maya Chen','maya@example.com'],['JL','Jordan Lee','jordan@example.com'],['SC','Sam Carter','sam@example.com'],['AR','Alex Rivera','alex@example.com']].map(([i,n,e])=>`<div class="toggle-row"><span style="display:flex;align-items:center;gap:10px"><b style="border-radius:50%;background:#e6edf7;padding:9px">${i}</b><span><b>${n}</b><small class="small-status" style="display:block">${e}</small></span></span><button class="app-input" data-contact="${n}">Details</button></div>`).join('')}</div></div>`}
function previewUI(){return `<div class="app-content" style="padding:20px;text-align:center"><div style="font-size:115px;margin:25px">📄</div><h2 class="app-title">Getting Started</h2><p class="app-subtitle">Canopy Document · 4 KB</p><div class="card" style="text-align:left"><h3>Welcome to CanopyOS</h3><p>Use the dock to open apps, press ⌘ Space to search, and explore System Settings. Your Notes and Reminders save on this device.</p></div><button class="app-input" data-action="preview-print">Print</button> <button class="app-input" data-action="preview-share">Share</button></div>`}
function voiceUI(){return `<div class="app-content" style="padding:24px;text-align:center"><h2 class="app-title">Voice Memos</h2><p class="app-subtitle">Capture an idea before it flies away.</p><div style="font-size:80px;color:#dc6b7d;margin:34px">◉</div><button class="primary" data-action="record-toggle" style="border-radius:25px;padding:12px 24px">● Start Recording</button><p class="small-status" style="margin-top:20px">Microphone isn't accessed in this demo.</p><div class="card" style="text-align:left;margin-top:20px"><h3>Recordings</h3><p>No recordings yet.</p></div></div>`}
function trashUI(){return `<div class="app-content" style="padding:22px"><h2 class="app-title">Trash</h2><p class="app-subtitle">Items stay here until you empty the trash.</p><div class="card"><p>The Trash is empty.</p><button data-action="trash-empty" class="app-input">Empty Trash</button></div></div>`}
const GUIDE_CATEGORIES=[['Desktop & navigation',['A live animated wallpaper canvas','Six animated wallpaper scenes','Energy-aware wallpaper pause on hidden tab','Adjustable wallpaper speed','Ambient wallpaper glow toggle','Dynamic date and clock menu bar','Local 12/24-hour clock setting','Weather glance widget','Date and calendar widget','Dock with running-app indicators','Dock hover lift feedback','Minimize, maximize, and close windows','Window focus and z-order management','App launcher with filtering','Global search across apps','Keyboard shortcut hints','Desktop context menu','Quick Control Center','Notification center','Focus mode quick toggle']],['Personalization & access',['Wallpaper picker in Settings','Desktop widget visibility setting','Reduced-motion accessibility option','High contrast toggle','Larger interface toggle','Brightness control','Volume control','Wi-Fi quick toggle','Bluetooth quick toggle','AirDrop quick toggle','Network status view','Dark appearance preference','Desktop icon visibility','Search apps by name','Search app descriptions','Keyboard shortcut reference','Battery and power information','About Canopy page','Privacy preferences','Local data clearing control']],['Files & productivity',['Finder home view','Downloads folder view','Desktop folder view','Recents view','Canopy Drive view','Personal, Work, and Important tags','File icon grid','New folder action','Create a note from Finder','Sort files action','Toggle file view action','Open file preview','Trash application','Auto-saving Notes','Create a new note','Copy note text','Clear note action','Reminder creation','Mark reminders complete','Delete reminders','Calendar month navigation']],['Built-in apps',['Calculator arithmetic','Calculator decimals and percentages','Calculator sign toggle','Calculator clear and chaining','World clock display','Add a world city','Countdown timer','Stopwatch controls','Weather current conditions','Hourly forecast glance','10-day forecast preview','Music playback controls','Music track selection','Music progress slider','Photos sample albums','Import photos affordance','Mail inbox preview','Compose mail affordance','Messages conversations','Send a local demo reply']],['Everyday tools & safety',['Maps place search affordance','Nearby places preview','Contacts search','Add contact affordance','Contact detail affordance','Preview document','Print/share actions','Voice memo recording affordance','Activity Monitor CPU estimate','Activity Monitor memory estimate','Running apps overview','Browser start page','Browser search simulation','Browser back and forward controls','Browser bookmark shortcuts','Keyboard shortcut ⌘ Space','Keyboard shortcut ⌘ ⇧ A','Keyboard shortcut ⌘ N','Keyboard shortcut ⌘ ,','Keyboard shortcut ⌘ W']],['Quiet details',['Search keyboard navigation','Escape closes overlays','Accessible button labels','Responsive mobile layout','Persistent wallpaper preference','Persistent appearance preference','Persistent Notes storage','Persistent Reminders storage','Persistent Calendar event storage','Local-only demo file list','No external account required','No location tracking','No microphone use in demo','No mail server connection','No real audio streaming','Reduced-motion system preference','Visibility-aware animation loop','Capped device pixel ratio','Efficient animation frame throttle','Clear local Canopy data']]];
function guideUI(){return `<div class="app-content" style="padding:20px"><div style="display:flex;justify-content:space-between;align-items:start"><div><h2 class="app-title">A calmer kind of desktop.</h2><p class="app-subtitle">A quick tour of the essentials built into CanopyOS.</p></div><span style="font:700 24px Manrope;color:#57b98e">100+</span></div><div class="card" style="background:linear-gradient(120deg,#e0f7ec,#e4efff)"><h3>Make yourself at home</h3><p>Open apps from the dock, search with ⌘ Space, or choose a live scene in Settings → Wallpaper. Your notes, reminders, and preferences save on this device.</p></div>${GUIDE_CATEGORIES.map(([title,list])=>`<div class="card"><h3>${title}</h3><div class="guide-list">${list.map(t=>`<div class="guide-feature"><b><span style="color:#54b28c">✓</span> ${esc(t)}</b><p>Thoughtfully tucked away until you need it.</p></div>`).join('')}</div></div>`).join('')}<p class="small-status">Some entries are convenience controls, previews, or demo affordances rather than connected services. CanopyOS is an open-source desktop concept.</p></div>`}

function renderLauncher(filter=''){let q=filter.toLowerCase();$('#launcherApps').innerHTML=APPS.filter(a=>a.name.toLowerCase().includes(q)||a.desc.toLowerCase().includes(q)).map(a=>`<button class="launcher-app" data-app="${esc(a.name)}"><span class="result-icon" style="${iconStyle(a)}">${a.icon}</span>${esc(a.name)}</button>`).join('')}
function closePanels(){['controlPanel','notificationsPanel','searchPanel','launcherBackdrop'].forEach(id=>$('#'+id).classList.add('hidden'));$('#contextMenu').classList.add('hidden')}
function openSearch(){closePanels();$('#searchPanel').classList.remove('hidden');$('#globalSearch').value='';searchResults('');setTimeout(()=>$('#globalSearch').focus(),10)}
function searchResults(query){const q=query.trim().toLowerCase();let matches=APPS.filter(a=>!q||a.name.toLowerCase().includes(q)||a.desc.toLowerCase().includes(q)).slice(0,8);$('#searchResults').innerHTML=matches.map(a=>`<button class="search-result" data-app="${esc(a.name)}"><span class="result-icon" style="${iconStyle(a)}">${a.icon}</span><span><b>${esc(a.name)}</b><small>${esc(a.desc)}</small></span></button>`).join('')+(q&&/^(new note|note)$/.test(q)?'<button class="search-result" data-app="Notes"><span class="result-icon">＋</span><span><b>New note</b><small>Create a quick note</small></span></button>':'');$('#searchResults .search-result')?.classList.add('selected')}
function contextMenu(x,y){let menu=$('#contextMenu');menu.style.left=x+'px';menu.style.top=y+'px';menu.innerHTML='<button data-action="context-launcher">▦ All Apps…</button><button data-action="context-new-note">＋ New Note</button><button data-action="context-wallpaper">Change Wallpaper…</button><button data-action="context-refresh">Refresh Desktop</button><button data-action="context-settings">Desktop Settings…</button>';menu.classList.remove('hidden')}
function refreshProcesses(){let list=$('#processList');if(!list)return;list.innerHTML=[...windows.values()].map(w=>`<div class="toggle-row"><span>${APPS.find(a=>a.name===w.app)?.icon||'◉'} &nbsp; ${esc(w.app)}</span><span class="small-status">${w.minimized?'Minimized':'Active'}</span></div>`).join('')||'<p>No running apps.</p>';$('#cpuStat').textContent=(4+Math.floor(Math.random()*17))+'%';$('#memStat').textContent=(1.1+Math.random()*.8).toFixed(1)+' GB'}
function monitorLoop(id){const w=windows.get(id);if(!w)return;refreshProcesses();setTimeout(()=>{if(windows.has(id))monitorLoop(id)},2200)}
function settingsUpdate(tab){let w=[...windows.values()].find(x=>x.app==='Settings'&&!x.minimized);if(w){$('#settingsPane',w.el).innerHTML=settingsPanel(tab);$$('[data-settings-tab]',w.el).forEach(x=>x.classList.toggle('active',x.dataset.settingsTab===tab))}}
function setPref(key,val){prefs[key]=val;savePrefs();if(key==='widgets')$('#desktopWidgets').classList.toggle('hidden',!val);if(key==='desktopIcons')$('#desktopIcons').classList.toggle('hidden',!val);if(key==='focus'){prefs.focus=val;$$('[data-control="focus"]').forEach(x=>x.classList.toggle('on',val));$('#focusToggle').style.opacity=val?'1':'.55';toast(val?'Focus is on. Notifications are quiet.':'Focus is off.')}if(key==='dark')document.body.classList.toggle('dark-mode',val);if(key==='highContrast')document.body.classList.toggle('high-contrast',val);if(key==='largeText')document.body.classList.toggle('large-text',val);if(key==='clock24')updateClock();if(key==='reduceMotion'){};let active=[...windows.values()].find(w=>w.app==='Settings'&&!w.minimized);if(active){let tab=$('.sidebar-item.active',active.el)?.dataset.settingsTab||'General';$('#settingsPane',active.el).innerHTML=settingsPanel(tab);}}
function currentWindow(target){return target.closest('.app-window')}
function refreshApp(name){let w=[...windows.values()].find(x=>x.app===name&&!x.minimized);if(w){let body=$('.window-body',w.el);body.innerHTML=renderApp(name);if(name==='Notes')$('#noteEditor',w.el).focus()}}
function calculate(key){let n=Number(calc.current);if(key==='AC'){calc={current:'0',stored:null,operator:null,reset:false}}else if(key==='±'){calc.current=String(-n)}else if(key==='%'){calc.current=String(n/100)}else if(['+','−','×','÷'].includes(key)){if(calc.stored!==null&&!calc.reset)doCalc();calc.stored=Number(calc.current);calc.operator=key;calc.reset=true}else if(key==='='){doCalc();calc.stored=null;calc.operator=null;calc.reset=true}else if(key==='.'){if(calc.reset){calc.current='0.';calc.reset=false}else if(!calc.current.includes('.'))calc.current+='.'}else if(/[0-9]/.test(key)){calc.current=calc.reset||calc.current==='0'?key:calc.current+key;calc.reset=false}let display=$('.calculator');if(display){$('#calcResult',display).textContent=calc.current.length>12?Number(calc.current).toPrecision(8):calc.current;$('#calcExpr',display).textContent=calc.operator&&calc.stored!==null?`${calc.stored} ${calc.operator}`:''}}
function doCalc(){let a=calc.stored,b=Number(calc.current);if(a===null)return;switch(calc.operator){case'+':calc.current=String(a+b);break;case'−':calc.current=String(a-b);break;case'×':calc.current=String(a*b);break;case'÷':calc.current=b===0?'Error':String(a/b);break}if(calc.current.length>12&&calc.current!=='Error')calc.current=String(Number(calc.current.toPrecision(10)))}
function terminalCommand(cmd){let out=$('#termOutput');if(!out)return;let line=document.createElement('div');line.className='terminal-line';line.textContent='guest@canopy:~$ '+cmd;out.append(line);const args=cmd.trim().split(/\s+/),c=args[0]?.toLowerCase();let answer='';if(c==='help')answer='Available: help, date, time, apps, open <app>, clear, echo <text>, whoami, ls, wallpaper, theme <name>, about';else if(c==='date')answer=new Date().toString();else if(c==='time')answer=new Date().toLocaleTimeString();else if(c==='apps')answer=APPS.map(a=>a.name).join(' · ');else if(c==='open'){let app=APPS.find(a=>a.name.toLowerCase()===args.slice(1).join(' ').toLowerCase());if(app){launch(app.name);answer=`Launching ${app.name}…`}else answer='App not found. Type apps to list available apps.'}else if(c==='clear'){out.innerHTML='';$('#termInput').value='';return}else if(c==='echo')answer=args.slice(1).join(' ');else if(c==='whoami')answer='guest · CanopyOS';else if(c==='ls')answer=files.map(f=>f.name).join('   ');else if(c==='wallpaper')answer=`Current live wallpaper: ${wallpapers[prefs.wallpaper]?.name||prefs.wallpaper}`;else if(c==='theme'){let key=args[1];if(wallpapers[key]){prefs.wallpaper=key;savePrefs();answer=`Live wallpaper changed to ${wallpapers[key].name}.`}else answer='Themes: aurora, ocean, dusk, ember, forest, cosmos';}else if(c==='about')answer='CanopyOS is an open-source desktop for the web.';else if(c)answer=`Command not found: ${c}. Type help.`;if(answer){let result=document.createElement('div');result.className='terminal-line';result.textContent=answer;out.append(result)}$('#termInput').value='';$('#terminal').scrollTop=$('#terminal').scrollHeight}
let stopwatchStarted=0,stopwatchElapsed=0,stopwatchTimer=null;
function tickStopwatch(){let el=$('#stopwatchDisplay');if(!el)return;let ms=stopwatchElapsed+(stopwatchStarted?Date.now()-stopwatchStarted:0),s=Math.floor(ms/1000),tenths=Math.floor(ms/100)%10;el.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}.${tenths}`}
function startClockTimers(){let w=[...windows.values()].find(x=>x.app==='Clock'&&!x.minimized);if(!w)return;clearInterval(timerInterval);timerInterval=setInterval(()=>{let el=$('#bigClock',w.el);if(el)el.textContent=new Date().toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',second:'2-digit'});$('#worldClocks',w.el)&&($('#worldClocks',w.el).innerHTML=worldCities());tickStopwatch()},500)}
function moveMonth(delta){calendarDate.setMonth(calendarDate.getMonth()+delta);refreshApp('Calendar')}
function addFile(name,type='Folder'){files.push({name,icon:type==='Folder'?'📁':type==='Note'?'📝':'📄',type,date:'Today'});localStorage.setItem('canopy.files',JSON.stringify(files));refreshApp('Finder');toast(`${name} created`)}
function openSettings(tab='General'){launch('Settings');setTimeout(()=>settingsUpdate(tab),20)}
function showSearchResult(){let first=$('.search-result.selected')||$('.search-result');if(first)launch(first.dataset.app)}

// All desktop interactions are delegated so windows can be replaced without losing behavior.
document.addEventListener('click',e=>{
 const appBtn=e.target.closest('[data-app]');if(appBtn){launch(appBtn.dataset.app);if(appBtn.closest('#launcherBackdrop'))closePanels();return}
 const win=e.target.closest('.app-window');const action=e.target.closest('[data-action]')?.dataset.action;
 if(e.target.closest('[data-win]')){let w=windows.get(+win.dataset.id),what=e.target.closest('[data-win]').dataset.win;if(what==='close')closeWindow(w.id);else if(what==='minimize'){w.minimized=true;w.el.classList.add('hidden');renderDock()}else if(what==='maximize'){if(!w.maximized){w.rect={left:w.el.style.left,top:w.el.style.top,width:w.el.style.width,height:w.el.style.height};w.el.style.left='12px';w.el.style.top='42px';w.el.style.width='calc(100vw - 24px)';w.el.style.height='calc(100vh - 105px)';w.maximized=true}else{Object.assign(w.el.style,w.rect);w.maximized=false}}return}
 if(e.target.closest('[data-settings-tab]')){settingsUpdate(e.target.closest('[data-settings-tab]').dataset.settingsTab);return}
 if(e.target.closest('[data-pref]')){let b=e.target.closest('[data-pref]'),key=b.dataset.pref;setPref(key,!prefs[key]);return}
 if(e.target.closest('[data-wall]')){prefs.wallpaper=e.target.closest('[data-wall]').dataset.wall;savePrefs();settingsUpdate('Wallpaper');toast(`${wallpapers[prefs.wallpaper].name} wallpaper is live`);return}
 if(e.target.closest('[data-control]')){let key=e.target.closest('[data-control]').dataset.control;if(key==='focus')setPref('focus',!prefs.focus);else{let el=e.target.closest('[data-control]');el.classList.toggle('on');toast(`${key[0].toUpperCase()+key.slice(1)} ${el.classList.contains('on')?'on':'off'}`)}return}
 if(e.target.closest('[data-folder]')){let name=e.target.closest('[data-folder]').dataset.folder;let w=currentWindow(e.target);$('.window-body',w).innerHTML=filesUI(name);return}if(e.target.closest('[data-file]')){launch('Preview');return}
 if(e.target.closest('[data-day]')){let key=e.target.closest('[data-day]').dataset.day,title=prompt(`Add an event for ${key}:`);if(title){events[key]=[...(events[key]||[]),title];localStorage.setItem('canopy.events',JSON.stringify(events));refreshApp('Calendar');toast('Event added to your calendar')}return}
 if(e.target.closest('[data-calc]')){calculate(e.target.closest('[data-calc]').dataset.calc);return}
 if(e.target.closest('[data-mailbox]')){$('#mailTitle',win).textContent=e.target.closest('[data-mailbox]').dataset.mailbox;return}
 if(e.target.closest('[data-mail]')){let i=+e.target.closest('[data-mail]').dataset.mail;toast(['Welcome to Canopy — Your desktop, your way.','A little breathing room — Three ideas to make today easier.','Your weekly note — A quiet recap of what matters.'][i]);return}
 if(e.target.closest('[data-chat]')){$('#chatTitle',win).textContent=e.target.closest('[data-chat]').dataset.chat;return}
 if(e.target.closest('[data-reminder-delete]')){reminders.splice(+e.target.closest('[data-reminder-delete]').dataset.reminder,1);localStorage.setItem('canopy.reminders',JSON.stringify(reminders));refreshApp('Reminders');return}
 if(e.target.closest('[data-track]')){musicIndex=+e.target.closest('[data-track]').dataset.track;musicPlaying=true;refreshApp('Music');return}
 if(e.target.closest('[data-photo]')){toast(`Viewing ${e.target.closest('[data-photo]').dataset.photo}`);return}
 if(e.target.closest('[data-contact]')){toast(`Contact card: ${e.target.closest('[data-contact]').dataset.contact}`);return}
 if(e.target.closest('[data-web]')){$('#browserAddress',win).value='canopy://'+e.target.closest('[data-web]').dataset.web.toLowerCase().replaceAll(' ','-');browserPage=e.target.closest('[data-web]').dataset.web;$('#browserPage',win).innerHTML=`<div class="browser-hero"><h1>${esc(browserPage)}</h1><p>This Canopy preview keeps navigation local and private.</p><button data-action="browser-home" class="primary">Back to Canopy Start</button></div>`;return}
 if(e.target.closest('[data-close]')){$('#'+e.target.closest('[data-close]').dataset.close).classList.add('hidden');return}
 if(action){switch(action){case'note-new':notes='';refreshApp('Notes');break;case'note-copy':navigator.clipboard?.writeText(notes).then(()=>toast('Note copied'));break;case'note-clear':if(confirm('Clear this note?')){notes='';localStorage.setItem('canopy.notes',notes);refreshApp('Notes')}break;case'file-new-folder':{let n=prompt('Name your folder:','Untitled Folder');if(n)addFile(n);break}case'file-new-note':{let n=prompt('Name your note:','Untitled Note');if(n){addFile(n,'Note');launch('Notes')}break}case'file-sort':files.reverse();localStorage.setItem('canopy.files',JSON.stringify(files));refreshApp('Finder');break;case'file-view':toast('Icon view is active');break;case'cal-prev':moveMonth(-1);break;case'cal-next':moveMonth(1);break;case'cal-today':calendarDate=new Date();refreshApp('Calendar');break;case'reminder-add':{let inp=$('#reminderInput',win);if(inp.value.trim()){reminders.push({text:inp.value.trim(),done:false});localStorage.setItem('canopy.reminders',JSON.stringify(reminders));refreshApp('Reminders')}break}case'browser-go':goBrowser(win);break;case'browser-reload':toast('Page refreshed');break;case'browser-home':$('#browserPage',win).innerHTML=browserHome();$('#browserAddress',win).value='canopy://start';break;case'browser-back':toast('No earlier page');break;case'browser-forward':toast('No later page');break;case'web-search':{let q=$('#webSearch',win)?.value||'';$('#browserAddress',win).value='Search: '+q;$('#browserPage',win).innerHTML=`<h2>Search results for “${esc(q)}”</h2><p>Web search is a local demo. External navigation is disabled.</p>`;break}case'chat-send':{let inp=$('#chatInput',win);if(inp.value.trim()){$('#chatMessages',win).insertAdjacentHTML('beforeend',`<p style="text-align:right;color:#5689df">${esc(inp.value)} · You</p>`);inp.value=''}break}case'chat-new':toast('Choose a contact to start a conversation');break;case'music-play':musicPlaying=!musicPlaying;refreshApp('Music');break;case'music-next':musicIndex=(musicIndex+1)%4;refreshApp('Music');break;case'music-prev':musicIndex=(musicIndex+3)%4;refreshApp('Music');break;case'clock-add':{let c=prompt('Add a city (New York, London, Tokyo, or San Diego):');if(c&&['New York','London','Tokyo','San Diego'].includes(c)){cities.push(c);refreshApp('Clock');startClockTimers()}else if(c)toast('Try New York, London, Tokyo, or San Diego');break}case'timer-start':{let seconds=(+$('#timerMinutes',win).value||1)*60,el=$('#timerDisplay',win);el.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;let timer=setInterval(()=>{seconds--;if(!win.isConnected){clearInterval(timer);return}el.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if(seconds<=0){clearInterval(timer);el.textContent='Done!';toast('Timer finished')}},1000);break}case'stopwatch-toggle':if(stopwatchStarted){stopwatchElapsed+=Date.now()-stopwatchStarted;stopwatchStarted=0;clearInterval(stopwatchTimer);e.target.textContent='Start'}else{stopwatchStarted=Date.now();stopwatchTimer=setInterval(tickStopwatch,100);e.target.textContent='Pause'}break;case'stopwatch-reset':stopwatchStarted=0;stopwatchElapsed=0;clearInterval(stopwatchTimer);tickStopwatch();break;case'photo-import':toast('Photo import is a demo affordance');break;case'photo-sort':toast('Albums sorted by date');break;case'map-search':toast(`Searching nearby for ${$('#mapSearch',win).value||'places'} (preview)`);break;case'contact-add':{let n=prompt('Contact name:');if(n)toast(`${n} added to your local contacts`);break}case'mail-compose':toast('Compose preview — mail service is not connected');break;case'preview-print':window.print();break;case'preview-share':toast('Sharing is not connected in this demo');break;case'record-toggle':toast('Microphone is not accessed in this demo');break;case'trash-empty':toast('Trash is already empty');break;case'notify-test':toast('This is a Canopy test notification');break;case'clear-data':if(confirm('Clear Canopy notes, reminders, events, and preferences from this browser?')){['canopy.prefs','canopy.notes','canopy.reminders','canopy.events','canopy.files'].forEach(k=>localStorage.removeItem(k));toast('Local Canopy data cleared. Refresh to reset.')}break;case'show-guide':launch('Canopy Guide');break;case'context-launcher':closePanels();renderLauncher();$('#launcherBackdrop').classList.remove('hidden');$('#launcherSearch').value='';$('#launcherSearch').focus();break;case'context-new-note':closePanels();launch('Notes');break;case'context-wallpaper':closePanels();openSettings('Wallpaper');break;case'context-refresh':toast('Desktop refreshed');break;case'context-settings':closePanels();openSettings('Desktop & Dock');break;}}
});
function goBrowser(win){let val=$('#browserAddress',win).value.trim();if(!val)return;if(val.startsWith('canopy://')){$('#browserPage',win).innerHTML=browserHome();return}$('#browserPage',win).innerHTML=`<div class="browser-hero"><h1>Search the web</h1><p>“${esc(val)}”</p><p>External browsing is disabled in this offline desktop preview.</p><button data-action="browser-home" class="primary">Canopy Start</button></div>`}

document.addEventListener('input',e=>{if(e.target.id==='noteEditor'){notes=e.target.value;localStorage.setItem('canopy.notes',notes);$('#noteMeta').textContent='Saved just now'}if(e.target.id==='globalSearch')searchResults(e.target.value);if(e.target.id==='launcherSearch')renderLauncher(e.target.value);if(e.target.dataset.prefRange){prefs[e.target.dataset.prefRange]=+e.target.value;savePrefs();let tab=$('.settings-category')?'Wallpaper':'General';let label=e.target.closest('label')?.querySelector('.small-status');if(label)label.textContent=prefs.speed.toFixed(1)+'×'}if(e.target.id==='contactSearch'){let q=e.target.value.toLowerCase();$$('#contactsList .toggle-row').forEach(row=>row.classList.toggle('hidden',!row.textContent.toLowerCase().includes(q)))}});
document.addEventListener('change',e=>{if(e.target.matches('[data-reminder]')){reminders[+e.target.dataset.reminder].done=e.target.checked;localStorage.setItem('canopy.reminders',JSON.stringify(reminders));refreshApp('Reminders')}if(e.target.id==='brightness'){prefs.brightness=+e.target.value;savePrefs()}if(e.target.id==='volume'){prefs.volume=+e.target.value;savePrefs()}});
document.addEventListener('keydown',e=>{const mod=e.metaKey||e.ctrlKey;if(mod&&e.code==='Space'){e.preventDefault();openSearch()}else if(mod&&e.shiftKey&&e.key.toLowerCase()==='a'){e.preventDefault();closePanels();renderLauncher();$('#launcherBackdrop').classList.remove('hidden');$('#launcherSearch').value='';setTimeout(()=>$('#launcherSearch').focus(),20)}else if(mod&&e.key.toLowerCase()==='n'){e.preventDefault();launch('Notes')}else if(mod&&e.key===','){e.preventDefault();openSettings()}else if(mod&&e.key.toLowerCase()==='w'){let w=[...windows.values()].filter(w=>!w.minimized).sort((a,b)=>+b.el.style.zIndex-+a.el.style.zIndex)[0];if(w)closeWindow(w.id)}else if(mod&&e.key.toLowerCase()==='m'){let w=[...windows.values()].filter(w=>!w.minimized).sort((a,b)=>+b.el.style.zIndex-+a.el.style.zIndex)[0];if(w){w.minimized=true;w.el.classList.add('hidden');renderDock()}}else if(e.key==='Escape'){closePanels()}else if(e.target.id==='globalSearch'&&(e.key==='ArrowDown'||e.key==='ArrowUp')){e.preventDefault();let items=$$('#searchResults .search-result'),index=items.findIndex(x=>x.classList.contains('selected'));items.forEach(x=>x.classList.remove('selected'));index=(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;if(items[index])items[index].classList.add('selected')}else if(e.target.id==='globalSearch'&&e.key==='Enter'){e.preventDefault();showSearchResult()}else if(e.target.id==='launcherSearch'&&e.key==='Enter'){let a=$('.launcher-app');if(a)launch(a.dataset.app);closePanels()}else if(e.target.id==='termInput'&&e.key==='Enter'){termHistory.push(e.target.value);terminalCommand(e.target.value)}else if(e.target.id==='termInput'&&e.key==='ArrowUp'){e.target.value=termHistory.at(-1)||''}});
$('#appleMenu').addEventListener('click',e=>contextMenu(15,37));$('#searchToggle').addEventListener('click',openSearch);$('#controlToggle').addEventListener('click',()=>{$('#controlPanel').classList.toggle('hidden');$('#notificationsPanel').classList.add('hidden')});$('#wifiToggle').addEventListener('click',()=>{$('#controlPanel').classList.toggle('hidden');$('#notificationsPanel').classList.add('hidden')});$('#focusToggle').addEventListener('click',()=>setPref('focus',!prefs.focus));$('#clock').addEventListener('click',()=>{$('#notificationsPanel').classList.toggle('hidden');$('#controlPanel').classList.add('hidden')});$('#desktop').addEventListener('contextmenu',e=>{if(e.target.closest('.app-window,.dock-wrap,.menubar'))return;e.preventDefault();contextMenu(e.clientX,e.clientY)});document.addEventListener('click',e=>{if(!e.target.closest('#contextMenu,#appleMenu')&&!e.target.closest('[data-action^="context"]'))$('#contextMenu').classList.add('hidden')});$$('.menu-link').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.menu==='Help')launch('Canopy Guide');else if(b.dataset.menu==='File')launch('Finder');else if(b.dataset.menu==='Edit')toast('Standard editing shortcuts are available');else if(b.dataset.menu==='View')openSettings('Desktop & Dock');else if(b.dataset.menu==='Window')toast('Use the dock to switch between windows')}));
$('#brightness').value=prefs.brightness;$('#volume').value=prefs.volume;$('#desktopWidgets').classList.toggle('hidden',!prefs.widgets);$('#desktopIcons').classList.toggle('hidden',getPrefs().desktopIcons===false);document.body.classList.toggle('dark-mode',prefs.dark);document.body.classList.toggle('high-contrast',!!prefs.highContrast);document.body.classList.toggle('large-text',!!prefs.largeText);$('#focusToggle').style.opacity=prefs.focus?'1':'.55';renderDock();renderLauncher();
